        getChartData(state) {
            var labels = state.domainState.engagementHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                metricsChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.engagementHistory },
                        { data: state.domainState.innovationHistory },
                        { data: state.domainState.coherenceHistory },
                        { data: state.domainState.compositeHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function (k) { return k; };
            var last = history[history.length - 1];
            var composite = last.results ? last.results.composite : 0;
            var performance = t('perf_critical');
            if (composite >= 85) performance = t('perf_excellent');
            else if (composite >= 75) performance = t('perf_good');
            else if (composite >= 65) performance = t('perf_acceptable');
            else if (composite >= 55) performance = t('perf_concerning');

            var avgComposite = history.reduce(function(s, r) { return s + (r.results ? r.results.composite : 0); }, 0) / history.length;

            var insights = [];
            if (last.results) {
                if (last.results.engagement >= 85) insights.push(t('insight_engagement_strong'));
                if (last.results.engagement < 70) insights.push(t('insight_engagement_low'));
                if (last.results.innovation >= 80) insights.push(t('insight_innovation_strong'));
                if (last.results.innovation < 65) insights.push(t('insight_innovation_low'));
                if (last.results.turnover <= 9) insights.push(t('insight_turnover_good'));
                if (last.results.turnover > 12) insights.push(t('insight_turnover_high'));
                if (last.results.coherence >= 80) insights.push(t('insight_coherence_strong'));
                if (last.results.coherence < 65) insights.push(t('insight_coherence_low'));
            }
            if (insights.length === 0) {
                insights.push(t('insight_mixed'));
            }

            return {
                finalComposite: composite,
                averageComposite: Math.round(avgComposite * 10) / 10,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.composite < 60) return window.mySimulation.t('hint_low_composite');
            if (results.turnover > 14) return window.mySimulation.t('hint_high_turnover');
            if (results.innovation < 65) return window.mySimulation.t('hint_low_innovation');
            if (results.coherence < 60) return window.mySimulation.t('hint_low_coherence');
            if (results.composite >= 80) return window.mySimulation.t('hint_strong');
            return null;
